export default function Cart({ cart, removeFromCart }) {
  return (
    <div className="cart">
      <h3>🧾 Cart</h3>

      {cart.length === 0 && <p>No items added</p>}

      {cart.map((item, index) => (
        <div key={index} className="cart-item">
          <span>{item.name} – ₹{item.price}</span>
          <button onClick={() => removeFromCart(index)}>❌</button>
        </div>
      ))}
    </div>
  );
}
